public static String testableHtml(PageData pageData, boolean includeSuiteSetup) throws Exception {
    WikiPage wikiPage = pageData.getWikiPage();
    StringBuffer buffer = new StringBuffer();

    includeSetupAndTeardown(pageData, includeSuiteSetup, buffer, wikiPage);

    buffer.append(pageData.getContent());

    pageData.setContent(buffer.toString());
    return pageData.getHTML();
}

private static void includeSetupAndTeardown(PageData pageData, boolean includeSuiteSetup, StringBuffer buffer, WikiPage wikiPage) throws Exception {
    if (pageData.hasAttribute("Test")) {
        if (includeSuiteSetup) {
            includePageSetup(buffer, wikiPage, SuiteResponder.SUITE_SETUP_NAME);
        }
        includePageSetup(buffer, wikiPage, "SetUp");
    }

    if (pageData.hasAttribute("Test")) {
        includePageTeardown(buffer, wikiPage, "TearDown");
        if (includeSuiteSetup) {
            includePageTeardown(buffer, wikiPage, SuiteResponder.SUITE_TEARDOWN_NAME);
        }
    }
}

private static void includePageSetup(StringBuffer buffer, WikiPage wikiPage, String pageName) throws Exception {
    WikiPage setup = PageCrawlerImpl.getInheritedPage(pageName, wikiPage);
    if (setup != null) {
        WikiPagePath setupPath = wikiPage.getPageCrawler().getFullPath(setup);
        String setupPathName = PathParser.render(setupPath);
        buffer.append("! include -setup .").append(setupPathName).append("\n");
    }
}

private static void includePageTeardown(StringBuffer buffer, WikiPage wikiPage, String pageName) throws Exception {
    WikiPage teardown = PageCrawlerImpl.getInheritedPage(pageName, wikiPage);
    if (teardown != null) {
        WikiPagePath tearDownPath = wikiPage.getPageCrawler().getFullPath(teardown);
        String tearDownPathName = PathParser.render(tearDownPath);
        buffer.append("\n").append("!include -teardown .").append(tearDownPathName).append("\n");
    }
}
